INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-01-training-009', 'p1b-m1-01-training', 'physics-b-1', 'p1b-m1', 3, '第 9 题', '一个质点沿 x 轴运动,其加速度和位置的关系为 $\scriptstyle a = 2 + 6 x ^ { 2 }$ 。已知质点在 $x _ { 0 } { = } 0$ 处,速度为 $\nu _ { 0 } { = } 1 0 m / s$ ,试求质点在任何坐标处的速度值。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '力学练习一.pdf 第9题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-001', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 1 题', '下列说法中,哪一个是正确的？', '["一质点在某时刻的瞬时速度是2 m/s,说明它在此后1 s内一定要经过2 m的路程","斜向上抛的物体,在最高点处的速度最小,加速度最大","物体作曲线运动时,有可能在某时刻的法向加速度为零","物体加速度越大,则速度越大。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习二.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-002', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 2 题', '质点作半径为 $R$ 的变速圆周运动时的加速度大小为（   ）（$v$ 表示任一时刻质点的速率）', '["$\\frac{dv}{dt}$","$\\frac{v^2}{R}$","$\\frac{v^2}{R} + \\frac{dv}{dt}$","$\\sqrt{\\left(\\frac{v^2}{R}\\right)^2 + \\left(\\frac{dv}{dt}\\right)^2}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '变速圆周运动的加速度由两个互相垂直的分量组成：

- **切向加速度**：$a_t = \frac{dv}{dt}$，改变速度大小。
- **法向加速度**：$a_n = \frac{v^2}{R}$，改变速度方向。

加速度是矢量，需用勾股定理合成：

$$a = \sqrt{a_n^2 + a_t^2} = \sqrt{\left(\frac{v^2}{R}\right)^2 + \left(\frac{dv}{dt}\right)^2}$$

故选 **D**。

注意：匀速圆周运动时 $\frac{dv}{dt}=0$，则 $a=\frac{v^2}{R}$（对应选项 B）。', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习二.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-003', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 3 题', '在一个转动的齿轮上,一个齿尖 P 沿半径为 R=0.2m 的圆周运动,其路程 S 随时间的变化规律为 $S = \nu _ { 0 } t + { \frac { 1 } { 2 } } b t ^ { 2 }$ ,其中 $\nu _ { 0 } { = } 2 \mathrm { m / s }$ 和 $b = 0 . 3 m / s ^ { 2 }$ 0则t=5s时齿尖P的总加速度大小a约等于', '["$3 4 \\mathrm { m } / \\mathrm { s } ^ { 2 }$","$4 2 \\mathrm { m } / \\mathrm { s } ^ { 2 }$","$5 1 \\mathrm { m } / \\mathrm { s } ^ { 2 }$","$6 1 \\mathrm { m } / \\mathrm { s } ^ { 2 }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '力学练习二.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-02-training-004', 'p1b-m1-02-training', 'physics-b-1', 'p1b-m1', 0, '第 4 题', '质点的质量为 $m$，置于光滑球面的顶点 $A$ 处（球面固定不动），如图所示。当它由静止开始下滑到球面上 $B$ 点时（设 $OB$ 与竖直方向夹角为 $\theta$），它的加速度的大小为（   ）', '["$a = g\\sqrt{1 - \\cos\\theta}$","$a = g\\sin\\theta$","$a = g$","$a = g\\sqrt{4\\sin^2\\theta + (1 - \\cos\\theta)^2}$"]'::jsonb, '3', '[]'::jsonb, NULL, NULL, NULL, '质点在光滑球面上运动，只有重力做功，机械能守恒。下降高度 $h = R(1-\cos\theta)$，故：

$$mgR(1-\cos\theta) = \frac{1}{2}mv^2$$

$$v^2 = 2gR(1-\cos\theta)$$

在自然坐标系下：

- **法向加速度**：$a_n = \frac{v^2}{R} = 2g(1-\cos\theta)$
- **切向加速度**：$a_t = g\sin\theta$

总加速度大小为：

$$a = \sqrt{a_n^2 + a_t^2} = g\sqrt{4(1-\cos\theta)^2 + \sin^2\theta}$$

故选 **D**。', NULL, NULL, '/physics/training/p1b-m1-02-training/d9ee40d816856f6b75588d5c5adde7fbe6076a36381795ded5d2220b3ba1b1f9.jpg', 1, '["选择题"]'::jsonb, '力学练习二.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
